typedef struct { bool (*match)(const msg_t *, void *); void *ctx; } msg_filter_t;

void pump(int in, int out, const msg_filter_t *f)
{
    msg_t m;
    while (msg_recv(in, &m) == 0) {
        if (f->match(&m, f->ctx)) msg_send(out, &m);  /* accepted */
        else filtered++;                              /* or discard_channel_send() */
    }
}
